const rel = $input.first().json;
const cfg = $('Definir Destinatário').first().json;

if (!/^[^@\s]+@(c|g)\.us$/.test(cfg.chatId)) {
  throw new Error('chatId inválido no node "Definir Destinatário" — use seu número (55+DDD+número @c.us) ou o ID de um grupo (@g.us). Grupo: GET http://localhost:3000/api/{sessao}/groups');
}

if (!rel.ok) {
  throw new Error(rel.erro || 'Falha ao gerar o relatório Windy');
}
if (!rel.imagem_base64) {
  throw new Error('Resposta não contém a imagem (imagem_base64)');
}

const bodyImagem = {
  session: cfg.session,
  chatId: cfg.chatId,
  file: {
    mimetype: 'image/png',
    filename: 'windy_' + rel.data + '_' + String(rel.horario).replace(/:/g, '-') + '.png',
    data: rel.imagem_base64,
  },
  caption: rel.resumo,
};

const bodyTexto = {
  session: cfg.session,
  chatId: cfg.chatId,
  text: '📄 *Relatório completo — Windy*\n\n' + rel.texto,
};

return [{ json: { chatId: cfg.chatId, resumo: rel.resumo, bodyImagem, bodyTexto } }];
